  const random=rng(0xC010A),wind=[];for(let i=0;i<240;i++){const a=random()*TAU,y=random()*2-1,r=Math.sqrt(1-y*y);wind.push(Math.cos(a)*r,y,Math.sin(a)*r,random(),.025+random()*.04,0,1.6+random()*2.2)}
