 resize(w,h){this.w=w;this.h=h;this.dpr=Math.min(window.devicePixelRatio||1,1.5);this.canvas.width=Math.round(w*this.dpr);this.canvas.height=Math.round(h*this.dpr);this.gl.viewport(0,0,this.canvas.width,this.canvas.height)}
