 setText('object-category',state.level==='surface'?'殖民地 / COLONY':state.planet===15?'深空目标 / ANOMALY':'行星档案 / PLANET');setText('object-number',pad(state.planet+1));setText('object-title',p.name);setText('object-subtitle',`[ 1 : ${activeSystem.id+1} : ${state.planet+1} ]  ${p.en}`);setText('object-status',p.status);setText('object-description',p.desc);
