function resize(){const previousW=w,previousH=h;w=innerWidth;h=innerHeight;if(R)R.resize(w,h);overlay.width=w;overlay.height=h;if(cam&&goal&&(w!==previousW||h!==previousH)){flight=null;state.flying=false;document.body.classList.remove('flying');$('travel-label').classList.remove('visible');goal=state.level==='galaxy'?galaxyCam():state.level==='system'?systemCam():state.level==='planet'?planetCam():beltCam();cam=copyCam(goal)}}
